styl:
.white-bg.b-new-text-19 {  background:#fff  }
.b-new-text-19 .small-title, .b-new-text-19 .title-top {  font-family:Helvetica!important;font-weight:700;color:#413e43  }
.b-new-text-19 .small-title {  letter-spacing:-.5px;font-size:32px;line-height:38px  }
.b-new-text-19 .little-big-text {  font-family:Helvetica!important;font-weight:700;font-size:18px;line-height:25px;color:#413e43  }
.b-new-text-19 .subtitle-min, .b-new-text-19 .text {  font-family:Helvetica!important  }
.b-new-text-19 .text {  letter-spacing:0;color:#413e43;font-size:18px;font-weight:400;line-height:27px  }
.b-new-text-19 .text.list {  display:list-item  }
.b-new-text-19 .pb8 {  padding-bottom:8px  }
.b-new-text-19 .pb12 {  padding-bottom:12px  }
.b-new-text-19 .pb44 {  padding-bottom:44px  }
.b-new-text-19 .pt44, .b-new-text-19 .pt45 {  padding-top:44px  }
.br-full-16.b-new-text-19 {  border-radius:16px;-moz-border-radius:16px;-webkit-border-radius:16px  }
.bg-bord-full.b-new-text-19 {  border:1px solid #eae9e9  }
.b-new-text-19 .text a, .b-new-text-19 b {  font-family:Helvetica!important  }
.b-new-text-19 .text a {  text-decoration:underline!important;font-weight:400;font-size:18px;line-height:27px;color:#1466fe!important  }
.b-new-text-19 .pb32 {  padding-bottom:32px  }
.b-new-text-19 .big-blue-text {  font-family:Helvetica!important;font-weight:700;font-size:56px;line-height:67px;color:#4575fe  }
@media screen and (max-width:600px) {
  .b-new-text-19 .big-blue-text {  font-size:36px!important;line-height:47px!important;text-align:center!important  }
}
.b-new-text-19 .fw-min-blue {  font-size:48px!important  }
.b-new-text-19 .left-block {  display:inline-block;width:230px;background:#f6f6f6;border-radius:24px;margin-right:10px;min-height:368px;vertical-align:top  }
@media screen and (max-width:600px) {
  .b-new-text-19 .left-block {  margin-right:0!important;width:100%!important;margin-bottom:20px!important;min-height:auto!important  }
}
.b-new-text-19 .pdd {  padding:24px  }
.b-new-text-19 .right-block {  display:inline-block;width:230px;background:#f6f6f6;border-radius:24px;min-height:368px;vertical-align:top  }
@media screen and (max-width:600px) {
  .b-new-text-19 .right-block {  width:100%!important;min-height:auto!important  }
}
.b-new-text-19 .blocks-text, .b-new-text-19 .min-grey {  font-family:Helvetica!important;font-weight:400;font-size:16px;line-height:24px;color:#7f7f7f  }
.b-new-text-19 .little-button {  padding:20px 0;width:100%;border:2px solid #3f3f3f;border-radius:12px;font-family:Helvetica!important;font-weight:700;font-size:18px;text-align:center;color:#3f3f3f  }
